practice_challenges.starter_code:
class ValidationError(ValueError):
    def __init__(self, problems):
        self.problems = problems
        super().__init__("; ".join(problems))

def validate_user(data):
    problems = []
    if not data.get("name"):
        problems.append("name is required")
    # TODO: add "email must contain '@'" when the email (default "") has no '@'
    # TODO: add "age must be an int >= 18" when age is missing, not an int, or < 18
    # TODO: raise ValidationError(problems) if the list is not empty
    return data

for user in [{"name": "Asha", "email": "a@x.io", "age": 30}, {"email": "nope", "age": 12}]:
    try:
        validate_user(user)
        print("valid")
    except ValidationError as e:
        print(len(e.problems), "problems:", e)

practice_challenges.test_code:
try:
    validate_user({})
except ValueError as e:
    assert e.problems == ["name is required", "email must contain '@'", "age must be an int >= 18"]
else:
    raise AssertionError
assert validate_user({"name": "B", "email": "b@b", "age": 18})["age"] == 18

